        LinearLayout queueCard=a.card(body,a.t("图片队列","Image queue"));a.buttons(queueCard,a.button(a.t("批量导入图片","Import images"),()->a.importImages(s,()->a.scheduleScramble(false))));a.scrambleQueue=a.queue(queueCard,s,()->a.scheduleScramble(a.scrambleReversePreview));
        LinearLayout p=a.card(body,a.t("图片预览","Image preview"));a.scrambleBefore=a.preview(p,a.t("原图","Original"));a.scrambleAfter=a.preview(p,a.t("混淆结果","Scrambled result"));a.bindEmptyPreview(a.scrambleBefore,()->a.importImages(s,()->a.scheduleScramble(a.scrambleReversePreview)));a.bindEmptyPreview(a.scrambleAfter,()->a.importImages(s,()->a.scheduleScramble(a.scrambleReversePreview)));
        EditText encRounds=roundInput(a,body,a.t("混淆次数","Scramble rounds"),s.scramble.Rounds,v->{s.scramble.Rounds=v;a.scheduleScramble(false);});EditText decRounds=roundInput(a,body,a.t("解混淆次数","Restore rounds"),s.scrambleDecodeRounds,v->{s.scrambleDecodeRounds=v;a.scheduleScramble(true);});body.addView(a.label(a.t("次数为 1–20 的整数，默认 1。混淆 2 次的图片需解混淆 2 次；两边移位系数须一致。","Rounds: integer 1–20, default 1. A twice-scrambled image needs two reverse rounds with the same shift coefficient."),12,false));
        body.addView(a.label(a.t("默认系数 1.0、无损 PNG、原尺寸、增绿关闭；导入后直接生成即可。","Defaults: shift 1.0, lossless PNG, original dimensions, green enhancement off. Import and generate."),12,false));
        LinearLayout q=a.card(body,a.t("混淆设置与输出","Scramble settings and output"));q.addView(a.label(a.t("Gilbert 曲线混淆：按原尺寸重新排列像素，默认移位系数为 1.0。关闭颜色调整、保持尺寸与像素不变，并用相同系数和次数解混淆，可还原图像像素。","Gilbert scrambling rearranges pixels at the original dimensions, with a default shift of 1.0. With color adjustments off, unchanged dimensions and pixels, and matching shift and rounds, image pixels can be restored."),13,false));
        String[] values=new String[21];for(int i=0;i<21;i++)values[i]=String.format(Locale.ROOT,"%.1f",i/10.0);
        Spinner enc=a.spinner(q,a.t("混淆移位系数","Scramble shift coefficient"),values,(int)Math.round(s.scramble.Strength*10),i->{s.scramble.Strength=i/10.0;a.scheduleScramble(false);});presets(a,q,enc);q.addView(a.label(a.t("移位系数为 0–2，0 表示不移位。更大的数值或更多次数不代表一定更强；解混淆需要相同系数和次数。","Shift coefficient: 0–2; 0 means no shift. Higher values or more rounds are not necessarily stronger. Restore with matching coefficient and rounds."),12,false));
